# I/O-bound: download many URLs with a thread pool
from concurrent.futures import ThreadPoolExecutor, as_completed
import requests

def download(url: str) -> tuple[str, int]:
    r = requests.get(url, timeout=30)      # GIL released while waiting on the socket
    return url, len(r.content)

urls = ["https://example.com"] * 8
with ThreadPoolExecutor(max_workers=4) as pool:
    futures = {pool.submit(download, u): u for u in urls}
    for fut in as_completed(futures):
        try:
            url, size = fut.result()
            print(url, size)
        except requests.RequestException as e:
            print("failed", futures[fut], e)
