# Race condition and the fix with a Lock
import threading

counter = 0
lock = threading.Lock()

def inc_unsafe():
    global counter
    for _ in range(100_000):
        counter += 1                       # read-modify-write: not atomic

def inc_safe():
    global counter
    for _ in range(100_000):
        with lock:
            counter += 1

threads = [threading.Thread(target=inc_safe) for _ in range(4)]
for t in threads: t.start()
for t in threads: t.join()
print(counter)   # 400000 reliably with the lock
