# Cooperative cancellation with threading.Event (+ killing a subprocess)
import subprocess, threading, time

def job(cancel: threading.Event, status: dict):
    proc = subprocess.Popen(["ping", "127.0.0.1", "-n", "100"],   # long external command
                            stdout=subprocess.DEVNULL)
    while proc.poll() is None:
        if cancel.is_set():
            proc.terminate()               # stop the child process
            status["state"] = "cancelled"
            return
        time.sleep(0.2)
    status["state"] = "done"

cancel, status = threading.Event(), {}
t = threading.Thread(target=job, args=(cancel, status))
t.start(); time.sleep(1); cancel.set(); t.join()
print(status)    # {'state': 'cancelled'}
```

