import threading, uuid
from concurrent.futures import ThreadPoolExecutor

executor = ThreadPoolExecutor(max_workers=4)
jobs: dict[str, dict] = {}
lock = threading.Lock()

def run_job(job_id, url, cancel: threading.Event):
    try:
        for pct in download_with_progress(url):     # yields progress
            if cancel.is_set():
                set_state(job_id, status="cancelled"); return
            set_state(job_id, progress=pct)
        set_state(job_id, status="done")
    except Exception as e:
        set_state(job_id, status="error", error=str(e))

def set_state(job_id, **kw):
    with lock:
        jobs[job_id].update(kw)

@app.post("/jobs")
def start(req: JobIn):
    job_id, cancel = uuid.uuid4().hex, threading.Event()
    jobs[job_id] = {"status": "running", "progress": 0, "cancel": cancel}
    executor.submit(run_job, job_id, req.url, cancel)
    return {"job_id": job_id}

@app.delete("/jobs/{job_id}")
def cancel(job_id: str):
    jobs[job_id]["cancel"].set()
```
Monitoring via polling or SSE that reads the job state. Limits: bounded pool to cap concurrency; cooperative cancellation (terminate subprocesses explicitly); state is lost on restart and doesn't work across multiple workers/replicas - at that point move to a real queue (SQS/Redis + workers) and store job state in a database.
